import { Suspense } from 'react'
import { RevenueChart } from './RevenueChart'
import { LatestInvoices } from './LatestInvoices'
import { CardStats } from './CardStats'

type DashboardData = {
  totalRevenue: number
  totalInvoices: number
  revenue: { month: string; amount: number }[]
  invoices: { id: string; name: string; amount: number }[]
}

async function getDashboardData(): Promise<DashboardData> {
  const res = await fetch('https://api.example.com/dashboard')
  return res.json()
}

// The page itself does not await anything, so the heading and section
// skeletons are part of the static pre-rendered shell. Only the data-driven
// sections stream in, each behind its own Suspense boundary.
export default function Page() {
  // Start the request once and share the promise across all sections.
  const data = getDashboardData()

  return (
    <main>
      <h1>Dashboard</h1>
      <Suspense fallback={<CardStatsSkeleton />}>
        <CardStatsSection data={data} />
      </Suspense>
      <Suspense fallback={<SectionSkeleton title="Revenue" className="chart" />}>
        <RevenueSection data={data} />
      </Suspense>
      <Suspense
        fallback={<SectionSkeleton title="Latest Invoices" className="invoices" />}
      >
        <InvoicesSection data={data} />
      </Suspense>
    </main>
  )
}

async function CardStatsSection({ data }: { data: Promise<DashboardData> }) {
  const { totalRevenue, totalInvoices } = await data
  return <CardStats totalRevenue={totalRevenue} totalInvoices={totalInvoices} />
}

async function RevenueSection({ data }: { data: Promise<DashboardData> }) {
  const { revenue } = await data
  return <RevenueChart revenue={revenue} />
}

async function InvoicesSection({ data }: { data: Promise<DashboardData> }) {
  const { invoices } = await data
  return <LatestInvoices invoices={invoices} />
}

function CardStatsSkeleton() {
  return (
    <div className="grid grid-cols-2 gap-4" aria-busy="true">
      <div className="card">
        <h2>Total Revenue</h2>
        <p className="skeleton">&nbsp;</p>
      </div>
      <div className="card">
        <h2>Total Invoices</h2>
        <p className="skeleton">&nbsp;</p>
      </div>
    </div>
  )
}

function SectionSkeleton({
  title,
  className,
}: {
  title: string
  className: string
}) {
  return (
    <div className={className} aria-busy="true">
      <h2>{title}</h2>
      <div className="skeleton">&nbsp;</div>
    </div>
  )
}
